  CONSTRAINT `tenant_user_points_tenant_user_profile__020729e2_fk_tenant_us` FOREIGN KEY (`tenant_user_profile_id`) REFERENCES `tenant_user_profile` (`id`),
  CONSTRAINT `points_not_zero` CHECK (((`points` > 0) or (`points` < 0))),
  CONSTRAINT `tenant_user_points_chk_1` CHECK ((`balance_before` >= 0)),
  CONSTRAINT `tenant_user_points_chk_2` CHECK ((`balance_after` >= 0)),
  CONSTRAINT `tenant_user_points_chk_3` CHECK ((`original_points` >= 0)),
  CONSTRAINT `tenant_user_points_chk_4` CHECK ((`source_id` >= 0)),
  CONSTRAINT `tenant_user_points_chk_5` CHECK ((`operator_id` >= 0)),
  CONSTRAINT `tenant_user_points_chk_6` CHECK ((`created_by_id` >= 0)),
  CONSTRAINT `valid_balance` CHECK ((`balance_after` = (`balance_before` + `points`))),
  CONSTRAINT `valid_balance_positive` CHECK ((`balance_after` >= 0)),
  CONSTRAINT `valid_tenant_multiplier` CHECK ((`tenant_multiplier` > 0))
