-- ----------------------------
-- Table structure for user_type_tag
-- ----------------------------
DROP TABLE IF EXISTS `user_type_tag`;
CREATE TABLE `user_type_tag` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tag_name` varchar(50) NOT NULL,
  `tag_code` varchar(20) NOT NULL,
  `tag_type` varchar(20) NOT NULL,
  `tag_color` varchar(7) NOT NULL,
  `tag_icon` varchar(100) NOT NULL,
  `tag_description` longtext NOT NULL,
  `permission_modifiers` json NOT NULL,
  `quota_modifiers` json NOT NULL,
  `price_config` json NOT NULL,
  `default_duration_days` int unsigned DEFAULT NULL,
  `max_duration_days` int unsigned DEFAULT NULL,
  `tag_level` int unsigned NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `is_assignable` tinyint(1) NOT NULL,
  `requires_payment` tinyint(1) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tag_code` (`tag_code`),
  KEY `idx_user_type_tag_type_active` (`tag_type`,`is_active`),
  KEY `idx_user_type_tag_assignable` (`is_active`,`is_assignable`),
  CONSTRAINT `user_type_tag_chk_1` CHECK ((`default_duration_days` >= 0)),
  CONSTRAINT `user_type_tag_chk_2` CHECK ((`max_duration_days` >= 0)),
  CONSTRAINT `user_type_tag_chk_3` CHECK ((`tag_level` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

